import React, { useState, useEffect } from 'react';
import TaskItem from './TaskItem';

function ChecklistView({ checklist, tasks, onBack, onUpdate }) {
  const getCompletionStatus = () => {
    if (tasks.length === 0) return { badge: 'incomplete', text: 'No tasks' };
    const completed = tasks.filter(t => t.completion_id).length;
    const total = tasks.length;
    const percentage = (completed / total) * 100;

    if (percentage === 100) return { badge: 'completed', text: `${completed}/${total} Complete` };
    if (percentage > 0) return { badge: 'partial', text: `${completed}/${total} Complete` };
    return { badge: 'incomplete', text: `${completed}/${total} Complete` };
  };

  const status = getCompletionStatus();

  return (
    <div className="main-content">
      <div className="page-header">
        <button 
          className="btn btn-secondary" 
          onClick={onBack}
          style={{ marginBottom: '15px' }}
        >
          ← Back to Tasks
        </button>
        <h1>{checklist.name}</h1>
        <p>{checklist.description}</p>
      </div>

      <div className="task-section">
        <div className="section-header">
          <h2>Tasks</h2>
          <span className={`completion-badge ${status.badge}`}>
            {status.text}
          </span>
        </div>
        <div className="task-list">
          {tasks.length === 0 ? (
            <p style={{ color: '#7f8c8d' }}>No tasks in this checklist</p>
          ) : (
            tasks.map(task => (
              <TaskItem key={task.id} task={task} onUpdate={onUpdate} />
            ))
          )}
        </div>
      </div>
    </div>
  );
}

export default ChecklistView;
